    elseif node.kind == Kind.JSDocPrivateTag then
        local n = node
        return (encoder.boolToByte(n.tagName ~= nil) << 0) | (encoder.boolToByte(n.comment ~= nil) << 1)
    elseif node.kind == Kind.JSDocProtectedTag then
