    elseif node.kind == Kind.JSDocSeeTag then
        local n = node
        return (encoder.boolToByte(n.tagName ~= nil) << 0) | (encoder.boolToByte(n.nameExpression ~= nil) << 1) | (encoder.boolToByte(n.comment ~= nil) << 2)
    elseif node.kind == Kind.JSDocImplementsTag then
        local n = node
