    elseif node.kind == Kind.JSDocAugmentsTag then
        local n = node
        return (encoder.boolToByte(n.tagName ~= nil) << 0) | (encoder.boolToByte(n.className ~= nil) << 1) | (encoder.boolToByte(n.comment ~= nil) << 2)
    elseif node.kind == Kind.JSDocSatisfiesTag then
        local n = node
        return (encoder.boolToByte(n.tagName ~= nil) << 0) | (encoder.boolToByte(n.typeExpression ~= nil) << 1) | (encoder.boolToByte(n.comment ~= nil) << 2)
    elseif node.kind == Kind.JSDocThrowsTag then
        local n = node
        return (encoder.boolToByte(n.tagName ~= nil) << 0) | (encoder.boolToByte(n.typeExpression ~= nil) << 1) | (encoder.boolToByte(n.comment ~= nil) << 2)
    elseif node.kind == Kind.JSDocThisTag then
        local n = node
