    elseif node.kind == Kind.JSDocImportTag then
        local n = node
        return (encoder.boolToByte(n.tagName ~= nil) << 0) | (encoder.boolToByte(n.importClause ~= nil) << 1) | (encoder.boolToByte(n.moduleSpecifier ~= nil) << 2) | (encoder.boolToByte(n.attributes ~= nil) << 3) | (encoder.boolToByte(n.comment ~= nil) << 4)
    elseif node.kind == Kind.JSDocCallbackTag then
