        return (encoder.boolToByte(n.tagName ~= nil) << 0) | (encoder.boolToByte(n.typeExpression ~= nil) << 1) | (encoder.boolToByte(n:Name() ~= nil) << 2) | (encoder.boolToByte(n.comment ~= nil) << 3)
    elseif node.kind == Kind.JSDocOverloadTag then
        local n = node
        return (encoder.boolToByte(n.tagName ~= nil) << 0) | (encoder.boolToByte(n.typeExpression ~= nil) << 1) | (encoder.boolToByte(n.comment ~= nil) << 2)
    elseif node.kind == Kind.JSDocTypedefTag then
        local n = node
        return (encoder.boolToByte(n.tagName ~= nil) << 0) | (encoder.boolToByte(n.typeExpression ~= nil) << 1) | (encoder.boolToByte(n:Name() ~= nil) << 2) | (encoder.boolToByte(n.comment ~= nil) << 3)
    elseif node.kind == Kind.JSDocSignature then
        local n = node
        return (encoder.boolToByte(n.typeParameters ~= nil) << 0) | (encoder.boolToByte(n.parameters ~= nil) << 1) | (encoder.boolToByte(n.type ~= nil) << 2)
    elseif node.kind == Kind.JSDocNameReference then
        local n = node
        return (encoder.boolToByte(n:Name() ~= nil) << 0)
    elseif node.kind == Kind.ModuleDeclaration then
        local n = node
        return (encoder.boolToByte(encoder.hasModifiers(n:Modifiers())) << 0) | (encoder.boolToByte(n:Name() ~= nil) << 1) | (encoder.boolToByte(n.body ~= nil) << 2)
    elseif node.kind == Kind.ImportEqualsDeclaration then
        local n = node
        return (encoder.boolToByte(encoder.hasModifiers(n:Modifiers())) << 0) | (encoder.boolToByte(n:Name() ~= nil) << 1) | (encoder.boolToByte(n.moduleReference ~= nil) << 2)
    elseif node.kind == Kind.ExportDeclaration then
        local n = node
        return (encoder.boolToByte(encoder.hasModifiers(n:Modifiers())) << 0) | (encoder.boolToByte(n.exportClause ~= nil) << 1) | (encoder.boolToByte(n.moduleSpecifier ~= nil) << 2) | (encoder.boolToByte(n.attributes ~= nil) << 3)
    elseif node.kind == Kind.ImportType then
        local n = node
        return (encoder.boolToByte(n.argument ~= nil) << 0) | (encoder.boolToByte(n.attributes ~= nil) << 1) | (encoder.boolToByte(n.qualifier ~= nil) << 2) | (encoder.boolToByte(n.typeArguments ~= nil) << 3)
    elseif node.kind == Kind.ImportClause then
        local n = node
        return (encoder.boolToByte(n:Name() ~= nil) << 0) | (encoder.boolToByte(n.namedBindings ~= nil) << 1)
    elseif node.kind == Kind.ImportSpecifier then
        local n = node
        return (encoder.boolToByte(n.propertyName ~= nil) << 0) | (encoder.boolToByte(n:Name() ~= nil) << 1)
    elseif node.kind == Kind.JSDocLink then
        local n = node
        return (encoder.boolToByte(n:Name() ~= nil) << 0)
    elseif node.kind == Kind.JSDocLinkPlain then
        local n = node
        return (encoder.boolToByte(n:Name() ~= nil) << 0)
    elseif node.kind == Kind.JSDocLinkCode then
        local n = node
        return (encoder.boolToByte(n:Name() ~= nil) << 0)
    elseif node.kind == Kind.TypeParameter then
        local n = node
        return (encoder.boolToByte(encoder.hasModifiers(n:Modifiers())) << 0) | (encoder.boolToByte(n:Name() ~= nil) << 1) | (encoder.boolToByte(n.constraint ~= nil) << 2) | (encoder.boolToByte(n.expression ~= nil) << 3) | (encoder.boolToByte(n.defaultType ~= nil) << 4)
    elseif node.kind == Kind.SyntheticReferenceExpression then
        local n = node
        return (encoder.boolToByte(n.expression ~= nil) << 0) | (encoder.boolToByte(n.thisArg ~= nil) << 1)
    elseif node.kind == Kind.JSDocTypeLiteral then
        local n = node
