    elseif node.kind == Kind.JSDocParameterTag or node.kind == Kind.JSDocPropertyTag then
        local n = node
        return (encoder.boolToByte(n.tagName ~= nil) << 0) | (encoder.boolToByte(n:Name() ~= nil) << 1) | (encoder.boolToByte(n.typeExpression ~= nil) << 2) | (encoder.boolToByte(n.comment ~= nil) << 3)
    else
        return 0
    end
end

function encoder.getNodeCommonData(node)
    if node.kind == Kind.Block then
        local n = node
        return (encoder.boolToByte(n.multiLine)) << 24
    elseif node.kind == Kind.HeritageClause then
        local n = node
        local tokenIdx = 0
        if n.token == Kind.ImplementsKeyword then
            tokenIdx = 1
        end
        return tokenIdx << 24
    elseif node.kind == Kind.ExportAssignment then
        local n = node
        return (encoder.boolToByte(n.isExportEquals)) << 24
    elseif node.kind == Kind.ExportSpecifier then
        local n = node
        return (encoder.boolToByte(n.isTypeOnly)) << 24
    elseif node.kind == Kind.PrefixUnaryExpression then
        local n = node
        local operatorIdx = 0
        if n.operator == Kind.MinusToken then
            operatorIdx = 1
        elseif n.operator == Kind.TildeToken then
            operatorIdx = 2
        elseif n.operator == Kind.ExclamationToken then
            operatorIdx = 3
        elseif n.operator == Kind.PlusPlusToken then
            operatorIdx = 4
        elseif n.operator == Kind.MinusMinusToken then
            operatorIdx = 5
        end
        return operatorIdx << 24
    elseif node.kind == Kind.PostfixUnaryExpression then
        local n = node
        local operatorIdx = 0
        if n.operator == Kind.MinusMinusToken then
            operatorIdx = 1
        end
        return operatorIdx << 24
    elseif node.kind == Kind.MetaProperty then
        local n = node
        local keywordTokenIdx = 0
        if n.keywordToken == Kind.NewKeyword then
            keywordTokenIdx = 1
        end
        return keywordTokenIdx << 24
    elseif node.kind == Kind.ArrayLiteralExpression then
        local n = node
        return (encoder.boolToByte(n.multiLine)) << 24
    elseif node.kind == Kind.ObjectLiteralExpression then
        local n = node
        return (encoder.boolToByte(n.multiLine)) << 24
    elseif node.kind == Kind.TypeOperator then
        local n = node
        local operatorIdx = 0
        if n.operator == Kind.ReadonlyKeyword then
            operatorIdx = 1
        elseif n.operator == Kind.UniqueKeyword then
            operatorIdx = 2
        end
        return operatorIdx << 24
    elseif node.kind == Kind.ImportAttributes then
        local n = node
        local tokenIdx = 0
        if n.token == Kind.AssertKeyword then
            tokenIdx = 1
        end
        return (encoder.boolToByte(n.multiLine))<<24 | tokenIdx<<25
    elseif node.kind == Kind.SyntheticExpression then
        return encoder.getNodeCommonData_SyntheticExpression(node)
    elseif node.kind == Kind.JsxText then
        local n = node
        return (encoder.boolToByte(n.containsOnlyTriviaWhiteSpaces)) << 24
    elseif node.kind == Kind.ModuleDeclaration then
        local n = node
        local keywordIdx = 0
        if n.keyword == Kind.NamespaceKeyword then
            keywordIdx = 1
        end
        return keywordIdx << 24
    elseif node.kind == Kind.ImportEqualsDeclaration then
        local n = node
        return (encoder.boolToByte(n.isTypeOnly)) << 24
    elseif node.kind == Kind.ExportDeclaration then
        local n = node
        return (encoder.boolToByte(n.isTypeOnly)) << 24
    elseif node.kind == Kind.ImportType then
        local n = node
        return (encoder.boolToByte(n.isTypeOf)) << 24
    elseif node.kind == Kind.ImportClause then
        local n = node
        local phaseModifierIdx = 0
        if n.phaseModifier == Kind.TypeKeyword then
            phaseModifierIdx = 1
        elseif n.phaseModifier == Kind.DeferKeyword then
            phaseModifierIdx = 2
        end
        return phaseModifierIdx << 24
    elseif node.kind == Kind.ImportSpecifier then
        local n = node
        return (encoder.boolToByte(n.isTypeOnly)) << 24
    elseif node.kind == Kind.JSDocTypeLiteral then
        local n = node
        return (encoder.boolToByte(n.isArrayType)) << 24
    elseif node.kind == Kind.JSDocParameterTag or node.kind == Kind.JSDocPropertyTag then
        local n = node
        return (encoder.boolToByte(n.isBracketed))<<24 | (encoder.boolToByte(n.isNameFirst))<<25
    end
    return 0
end

function encoder.recordNodeStrings(node, strs)
    if node.kind == Kind.Identifier then
        return strs:add(node.text, node.kind, node:Pos(), node:End())
    elseif node.kind == Kind.PrivateIdentifier then
        return strs:add(node.text, node.kind, node:Pos(), node:End())
    elseif node.kind == Kind.JsxText then
        return strs:add(node.text, node.kind, node:Pos(), node:End())
    elseif node.kind == Kind.JSDocText then
        return strs:add(node:Text(), node.kind, node:Pos(), node:End())
    elseif node.kind == Kind.JSDocLink then
        return strs:add(node:Text(), node.kind, node:Pos(), node:End())
    elseif node.kind == Kind.JSDocLinkPlain then
        return strs:add(node:Text(), node.kind, node:Pos(), node:End())
    elseif node.kind == Kind.JSDocLinkCode then
        return strs:add(node:Text(), node.kind, node:Pos(), node:End())
    else
        error("Unexpected node kind " .. ast.Kind_String(node.kind), 0)
    end
end

function encoder.recordExtendedData(node, strs, positionMap, extendedData, structuredData)
    local offset = #extendedData * 4
    if node.kind == Kind.StringLiteral then
        encoder.recordExtendedData_StringLiteral(node, strs, positionMap, extendedData, structuredData)
    elseif node.kind == Kind.NumericLiteral then
        encoder.recordExtendedData_NumericLiteral(node, strs, positionMap, extendedData, structuredData)
    elseif node.kind == Kind.BigIntLiteral then
        encoder.recordExtendedData_BigIntLiteral(node, strs, positionMap, extendedData, structuredData)
    elseif node.kind == Kind.RegularExpressionLiteral then
        encoder.recordExtendedData_RegularExpressionLiteral(node, strs, positionMap, extendedData, structuredData)
    elseif node.kind == Kind.NoSubstitutionTemplateLiteral then
        encoder.recordExtendedData_NoSubstitutionTemplateLiteral(node, strs, positionMap, extendedData, structuredData)
    elseif node.kind == Kind.TemplateHead then
        encoder.recordExtendedData_TemplateHead(node, strs, positionMap, extendedData, structuredData)
    elseif node.kind == Kind.TemplateMiddle then
        encoder.recordExtendedData_TemplateMiddle(node, strs, positionMap, extendedData, structuredData)
    elseif node.kind == Kind.TemplateTail then
        encoder.recordExtendedData_TemplateTail(node, strs, positionMap, extendedData, structuredData)
    elseif node.kind == Kind.SourceFile then
        encoder.recordExtendedData_SourceFile(node, strs, positionMap, extendedData, structuredData)
    else
        error("unknown extended data node kind " .. ast.Kind_String(node.kind), 0)
    end
    return offset
end
